const recoveryGroups={
  'Airway & breathing':['Assign a trained recovery observer and maintain direct observation','Assess airway patency, respiratory effort, respiratory rate, and oxygenation','Confirm protective airway reflexes and clinician-approved extubation readiness','Record extubation time and continue airway / oxygen support as indicated'],
  'Circulation & temperature':['Continue heart rate / rhythm, blood pressure, and perfusion assessment','Recheck body temperature and provide monitored warming as indicated','Review fluid balance, surgical bleeding, incision, and dressings','Maintain IV access until clinician-approved removal criteria are met'],
  'Comfort & handoff':['Assess pain using a species-appropriate validated scale; document scale and score','Assess nausea, dysphoria, agitation, and response to prescribed treatment','Reassess alertness, posture, mobility, and temperature against the patient baseline','Document complications, treatments, and the ongoing monitoring plan','Complete clinician-approved transfer / discharge criteria and handoff']
};
let recoveryChecked=new Set(),recoveryNotes='',recoveryTimes={end:'',extubation:'',handoff:''};
let monitoringRows=[],rowId=0,monitorMeta={procedure:'',clinician:'',date:''};
const columns=[['time','Time','time',''],['day','Day offset','number','0 = record date'],['phase','Phase','phase',''],['hr','HR','number','bpm'],['rr','RR','number','/min'],['spo2','SpO₂','number','%'],['etco2','ETCO₂','number','mmHg'],['sap','SAP','number','mmHg'],['map','MAP','number','mmHg'],['dap','DAP','number','mmHg'],['temp','Temp','number','°C'],['inhalant','Inhalant','number','%'],['fluids','Fluids','number','mL/hr'],['notes','Assessment / interventions','text','']];
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function localTime(){const d=new Date();return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}
function addMonitoringRow(){const r={id:++rowId,time:localTime(),day:'0',phase:'Maintenance'};columns.forEach(([key])=>{if(!(key in r))r[key]=''});monitoringRows.push(r);return r}
function recordField(key,label,value,group,type='text'){return `<label>${label}<input type="${type}" data-${group}="${key}" value="${escapeHtml(value)}"><span class="printvalue">${escapeHtml(value)||'—'}</span></label>`}
function renderRecords(){let h='';
if(page===6){h=head('Post-op recovery checklist','Continue observation and reassessment throughout recovery; use individualized transfer criteria.')+`<div class="alert">Checklist completion does not establish readiness for extubation or discharge. A veterinarian determines airway management, treatment, and transfer criteria, including special precautions for airway disease.</div><article class="card"><div class="recordmeta">${recordField('end','Anesthesia ended',recoveryTimes.end,'recovery-time','time')}${recordField('extubation','Extubation',recoveryTimes.extubation,'recovery-time','time')}${recordField('handoff','Handoff',recoveryTimes.handoff,'recovery-time','time')}</div><p id="recoveryCount"></p><progress id="recoveryProgress" max="13"></progress></article><div class="grid category">`;let i=0;for(const [title,items]of Object.entries(recoveryGroups)){h+=`<article class="card checks"><h3>${title}</h3>`+items.map(text=>{const id=i++;return `<label><input type="checkbox" data-recovery-check="${id}" ${recoveryChecked.has(id)?'checked':''}>${text}</label>`}).join('')+'</article>'}h+=`</div><article class="card"><label>Recovery notes · pain scale / score, treatments, response, handoff recipient<textarea id="recoveryNotes" rows="5" placeholder="Document recovery assessments and the ongoing care plan">${escapeHtml(recoveryNotes)}</textarea><span class="printvalue">${escapeHtml(recoveryNotes)||'—'}</span></label><div class="recordactions"><button class="outline" id="exportRecovery">Download recovery record</button><button class="outline" id="resetRecovery">Reset recovery checklist</button></div></article>`+source(anesthesiaRef,'AAHA 2020 · recovery monitoring and care')}
if(page===7){h=head('Anesthetic monitoring sheet','Manual observations · record assessments during induction, maintenance, and recovery.')+`<div class="alert">This sheet records observations; it does not connect to monitors or provide alarms. Record at your facility’s required intervals while maintaining continuous patient observation. Blank cells mean not recorded.</div><article class="card"><div class="recordmeta">${recordField('procedure','Procedure',monitorMeta.procedure,'monitor-meta')}${recordField('clinician','Anesthetist / observer',monitorMeta.clinician,'monitor-meta')}${recordField('date','Record date',monitorMeta.date,'monitor-meta','date')}</div><div class="recordactions"><button class="outline" id="addVitals">+ Add observation</button><button class="outline" id="exportVitals">Download CSV</button><span>${monitoringRows.length} observations · values retained while switching tools</span></div><p class="ref">Record all temperatures in °C. Use notes for ECG rhythm, depth, mucous membranes / CRT, pain scale and score, oxygen flow, drugs, boluses, and interventions. For records crossing midnight, set Day offset to 1 for the following day (2 for the next, etc.). Graphs use time plus this day offset.</p><div class="tablewrap"><table class="vitalstable"><caption>Anesthesia observations · manual entry</caption><thead><tr>${columns.map(([,title,,unit])=>`<th scope="col">${title}<small>${unit}</small></th>`).join('')}<th class="noprint">Action</th></tr></thead><tbody>${monitoringRows.map(row=>`<tr>${columns.map(([key,title,type])=>`<td>${type==='phase'?`<select aria-label="${title}, observation ${row.id}" data-row="${row.id}" data-column="${key}">${['Induction','Maintenance','Recovery'].map(p=>`<option ${row[key]===p?'selected':''}>${p}</option>`).join('')}</select>`:`<input aria-label="${title}, observation ${row.id}" data-row="${row.id}" data-column="${key}" type="${type}" ${type==='number'?'min="0" step="any"':''} ${key==='spo2'?'max="100"':''} value="${escapeHtml(row[key])}">`}<span class="printvalue">${escapeHtml(row[key])||'—'}</span></td>`).join('')}<td class="noprint"><button class="outline" data-remove-row="${row.id}" aria-label="Remove observation ${row.id}">Remove</button></td></tr>`).join('')}</tbody></table></div>${monitoringRows.length?'':'<p class="empty">No observations yet. Add a row to start your monitoring record.</p>'}</article><section id="trendGraphs" aria-label="Vital parameter trend graphs"></section>`+source(anesthesiaRef,'AAHA 2020 · anesthesia monitoring and recovery')}
$('#content').innerHTML=h;calculate();updateRecoveryCount();if(page===7)renderTrends();}
function updateRecoveryCount(){if($('#recoveryCount')){$('#recoveryCount').textContent=`${recoveryChecked.size} / 13 recovery items complete`;$('#recoveryProgress').value=recoveryChecked.size}}
function patientRecord(){return {patient:$('#name').value,species:$('#species').value,weight:$('#weight').value,weightUnit:$('#weightUnit').value}}
function downloadRecord(contents,type,filename){const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(value){let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function monitoringCsv(){const p=patientRecord();const rows=[['Pocket Vet — anesthesia monitoring'],['Patient',p.patient,'Species',p.species,'Weight',p.weight,p.weightUnit],['Procedure',monitorMeta.procedure,'Observer',monitorMeta.clinician,'Date',monitorMeta.date],[],columns.map(([,title,,unit])=>title+(unit?' ('+unit+')':'')),...monitoringRows.map(r=>columns.map(([key])=>r[key]))];return '\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n')}
document.addEventListener('input',e=>{const t=e.target;let value=t.value;
if(t.dataset.row){const r=monitoringRows.find(r=>r.id===Number(t.dataset.row));if(r)r[t.dataset.column]=value;if(page===7)renderTrends();}
if(t.dataset.monitorMeta)monitorMeta[t.dataset.monitorMeta]=value;
if(t.dataset.recoveryTime)recoveryTimes[t.dataset.recoveryTime]=value;
if(t.id==='recoveryNotes')recoveryNotes=value;
if(t.nextElementSibling?.classList.contains('printvalue'))t.nextElementSibling.textContent=value||'—';
});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.recoveryCheck!==undefined){const id=Number(t.dataset.recoveryCheck);t.checked?recoveryChecked.add(id):recoveryChecked.delete(id);updateRecoveryCount()}if(t.dataset.column==='phase'){const r=monitoringRows.find(r=>r.id===Number(t.dataset.row));if(r)r.phase=t.value;if(page===7)renderTrends();if(t.nextElementSibling)t.nextElementSibling.textContent=t.value}});
document.addEventListener('click',e=>{const t=e.target;
if(t.id==='addVitals'){addMonitoringRow();render()}
if(t.dataset.removeRow){const row=monitoringRows.find(r=>r.id===Number(t.dataset.removeRow));if(row&&(!columns.some(([key])=>!['time','day','phase'].includes(key)&&row[key]!=='' )||window.confirm('Remove this observation? Export first if you need to retain it.'))){monitoringRows=monitoringRows.filter(r=>r!==row);render()}}
if(t.id==='resetRecovery'&&window.confirm('Clear recovery checks, times, and notes? Download the record first if needed.')){recoveryChecked.clear();recoveryNotes='';recoveryTimes={end:'',extubation:'',handoff:''};render()}
if(t.id==='exportVitals')downloadRecord(monitoringCsv(),'text/csv;charset=utf-8','pocket-vet-monitoring.csv');
if(t.id==='exportRecovery'){const items=Object.values(recoveryGroups).flat().map((text,i)=>`${recoveryChecked.has(i)?'[x]':'[ ]'} ${text}`);const p=patientRecord();downloadRecord(`Pocket Vet — post-op recovery\nPatient: ${p.patient}\nSpecies: ${p.species}\nWeight: ${p.weight} ${p.weightUnit}\nAnesthesia ended: ${recoveryTimes.end}\nExtubation: ${recoveryTimes.extubation}\nHandoff: ${recoveryTimes.handoff}\n\n${items.join('\n')}\n\nRecovery notes:\n${recoveryNotes}\n\nChecklist completion does not establish discharge readiness.`, 'text/plain;charset=utf-8','pocket-vet-recovery.txt')}
});
window.addEventListener('beforeunload',e=>{if(monitoringRows.length||recoveryChecked.size||recoveryNotes||Object.values(recoveryTimes).some(Boolean)){e.preventDefault();e.returnValue=''}});
